class Solution:
    def mySqrt(self, x: int) -> int:
        lo, hi = 0, x
        while lo < hi:
            mid = (lo + hi + 1) // 2      # upper mid so lo = mid always makes progress
            if mid * mid <= x:
                lo = mid                  # mid is a valid root candidate
            else:
                hi = mid - 1
        return lo

